```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Dune Line — Overnight Trans-Desert Express to New Veridia</title>
  <style>
    :root {
      --bg-void: #07060b;
      --bg-surface: #0f0d16;
      --bg-elevated: #171422;
      --bg-glass: rgba(15, 13, 22, 0.78);
      --border-subtle: rgba(228, 182, 115, 0.14);
      --border-bright: rgba(228, 182, 115, 0.36);
      --text-primary: #f5efe6;
      --text-secondary: #a89f93;
      --text-muted: #706861;
      --gold: #e4b673;
      --gold-soft: rgba(228, 182, 115, 0.12);
      --terracotta: #df6d44;
      --neon-cyan: #2af5e4;
      --neon-magenta: #ff3b8d;
      --font-serif: "Iowan Old Style", "Palatino Linotype", "Book Antiqua", Georgia, serif;
      --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      --font-mono: "SF Mono", "Fira Code", Menlo, Consolas, "Liberation Mono", monospace;
      --radius-sm: 6px;
      --radius-md: 12px;
      --radius-lg: 20px;
      --container: 1200px;
      --transition: 240ms cubic-bezier(0.22, 1, 0.36, 1);
    }

    *, *::before, *::after {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    html {
      scroll-behavior: smooth;
      background-color: var(--bg-void);
      color: var(--text-primary);
      font-family: var(--font-sans);
      -webkit-font-smoothing: antialiased;
      -moz-osx-font-smoothing: grayscale;
    }

    body {
      line-height: 1.6;
      overflow-x: hidden;
      background:
        radial-gradient(ellipse 80% 50% at 15% 0%, rgba(223, 109, 68, 0.08), transparent 60%),
        radial-gradient(ellipse 70% 45% at 88% 12%, rgba(42, 245, 228, 0.07), transparent 60%),
        var(--bg-void);
    }

    ::selection {
      background: var(--gold);
      color: var(--bg-void);
    }

    a {
      color: inherit;
      text-decoration: none;
    }

    button {
      font-family: inherit;
      cursor: pointer;
      border: none;
      background: none;
      color: inherit;
    }

    .container {
      width: 100%;
      max-width: var(--container);
      margin: 0 auto;
      padding: 0 32px;
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      font-family: var(--font-mono);
      font-size: 0.75rem;
      letter-spacing: 0.18em;
      text-transform: uppercase;
      color: var(--gold);
    }

    .eyebrow::before {
      content: "";
      width: 24px;
      height: 1px;
      background: linear-gradient(90deg, var(--gold), transparent);
    }

    .section {
      padding: 96px 0;
      position: relative;
    }

    .section-header {
      display: flex;
      justify-content: space-between;
      align-items: flex-end;
      gap: 32px;
      margin-bottom: 52px;
    }

    .section-title {
      font-family: var(--font-serif);
      font-weight: 400;
      font-size: clamp(2rem, 3.2vw, 2.85rem);
      line-height: 1.14;
      letter-spacing: -0.015em;
      margin-top: 14px;
      color: var(--text-primary);
    }

    .section-desc {
      max-width: 420px;
      color: var(--text-secondary);
      font-size: 0.98rem;
      line-height: 1.65;
    }

    /* Buttons */
    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 10px;
      padding: 13px 24px;
      border-radius: var(--radius-sm);
      font-size: 0.88rem;
      font-weight: 500;
      letter-spacing: 0.04em;
      transition: transform var(--transition), box-shadow var(--transition), background var(--transition), border-color var(--transition);
    }

    .btn-primary {
      background: linear-gradient(135deg, #ecc588 0%, #d49b54 100%);
      color: #0b090e;
      box-shadow: 0 8px 28px rgba(228, 182, 115, 0.22);
    }

    .btn-primary:hover {
      transform: translateY(-2px);
      box-shadow: 0 12px 34px rgba(228, 182, 115, 0.34);
    }

    .btn-secondary {
      background: rgba(255, 255, 255, 0.03);
      border: 1px solid var(--border-bright);
      color: var(--text-primary);
    }

    .btn-secondary:hover {
      background: rgba(228, 182, 115, 0.08);
      border-color: var(--gold);
      transform: translateY(-2px);
    }

    /* Navigation */
    .navbar {
      position: sticky;
      top: 0;
      z-index: 50;
      background: var(--bg-glass);
      backdrop-filter: blur(16px);
      -webkit-backdrop-filter: blur(16px);
      border-bottom: 1px solid var(--border-subtle);
    }

    .nav-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 76px;
    }

    .brand {
      display: flex;
      align-items: center;
      gap: 14px;
    }

    .brand-mark {
      width: 38px;
      height: 38px;
      flex-shrink: 0;
    }

    .brand-text {
      display: flex;
      flex-direction: column;
    }

    .brand-name {
      font-family: var(--font-serif);
      font-size: 1.25rem;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      line-height: 1;
      color: var(--text-primary);
    }

    .brand-sub {
      font-family: var(--font-mono);
      font-size: 0.64rem;
      letter-spacing: 0.16em;
      color: var(--gold);
      margin-top: 4px;
    }

    .nav-links {
      display: flex;
      align-items: center;
      gap: 36px;
      list-style: none;
    }

    .nav-links a {
      font-size: 0.88rem;
      color: var(--text-secondary);
      letter-spacing: 0.03em;
      position: relative;
      transition: color var(--transition);
    }

    .nav-links a::after {
      content: "";
      position: absolute;
      left: 0;
      bottom: -6px;
      width: 0;
      height: 1px;
      background: var(--gold);
      transition: width var(--transition);
    }

    .nav-links a:hover {
      color: var(--text-primary);
    }

    .nav-links a:hover::after {
      width: 100%;
    }

    .nav-actions {
      display: flex;
      align-items: center;
      gap: 16px;
    }

    .nav-status {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      font-family: var(--font-mono);
      font-size: 0.72rem;
      color: var(--neon-cyan);
      padding: 6px 12px;
      border-radius: 999px;
      background: rgba(42, 245, 228, 0.06);
      border: 1px solid rgba(42, 245, 228, 0.22);
    }

    .pulse-dot {
      width: 6px;
      height: 6px;
      border-radius: 50%;
      background: var(--neon-cyan);
      box-shadow: 0 0 8px var(--neon-cyan);
      animation: pulse 2.2s infinite ease-in-out;
    }

    @keyframes pulse {
      0%, 100% { opacity: 1; transform: scale(1); }
      50% { opacity: 0.45; transform: scale(0.8); }
    }

    .menu-toggle {
      display: none;
      width: 40px;
      height: 40px;
      border-radius: var(--radius-sm);
      border: 1px solid var(--border-subtle);
      align-items: center;
      justify-content: center;
    }

    /* Hero Section */
    .hero {
      padding: 64px 0 76px;
      position: relative;
    }

    .hero-top {
      display: grid;
      grid-template-columns: 1.2fr 0.8fr;
      gap: 48px;
      align-items: end;
      margin-bottom: 44px;
    }

    .hero-title {
      font-family: var(--font-serif);
      font-weight: 400;
      font-size: clamp(2.8rem, 4.8vw, 4.35rem);
      line-height: 1.06;
      letter-spacing: -0.02em;
      margin-top: 18px;
    }

    .hero-title em {
      font-style: italic;
      background: linear-gradient(90deg, var(--gold) 0%, #f5d8aa 45%, var(--neon-cyan) 100%);
      -webkit-background-clip: text;
      background-clip: text;
      color: transparent;
    }

    .hero-right {
      display: flex;
      flex-direction: column;
      gap: 24px;
      padding-bottom: 6px;
    }

    .hero-copy {
      font-size: 1.05rem;
      color: var(--text-secondary);
      line-height: 1.7;
    }

    .hero-cta-row {
      display: flex;
      flex-wrap: wrap;
      gap: 14px;
      align-items: center;
    }

    /* Hero Panorama Artwork */
    .hero-stage {
      position: relative;
      border-radius: var(--radius-lg);
      overflow: hidden;
      border: 1px solid var(--border-subtle);
      background: #0b0913;
      box-shadow: 0 30px 80px rgba(0, 0, 0, 0.65);
    }

    .hero-svg {
      display: block;
      width: 100%;
      height: auto;
    }

    .star-twinkle {
      animation: twinkle 4s infinite ease-in-out;
    }
    .star-twinkle.d2 { animation-delay: 1.3s; }
    .star-twinkle.d3 { animation-delay: 2.7s; }

    @keyframes twinkle {
      0%, 100% { opacity: 0.9; }
      50% { opacity: 0.25; }
    }

    .train-glide {
      animation: subtleFloat 6s infinite ease-in-out;
    }

    @keyframes subtleFloat {
      0%, 100% { transform: translateX(0px); }
      50% { transform: translateX(6px); }
    }

    .hero-telemetry {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      border-top: 1px solid var(--border-subtle);
      background: rgba(12, 10, 18, 0.92);
    }

    .telemetry-cell {
      padding: 20px 26px;
      border-right: 1px solid var(--border-subtle);
      display: flex;
      flex-direction: column;
      gap: 4px;
    }

    .telemetry-cell:last-child {
      border-right: none;
    }

    .telemetry-label {
      font-family: var(--font-mono);
      font-size: 0.68rem;
      letter-spacing: 0.14em;
      text-transform: uppercase;
      color: var(--text-muted);
    }

    .telemetry-value {
      font-family: var(--font-mono);
      font-size: 1.05rem;
      color: var(--text-primary);
    }

    .telemetry-value span {
      color: var(--gold);
    }

    /* Feature Highlights */
    .features-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 24px;
    }

    .feature-card {
      background: linear-gradient(180deg, var(--bg-elevated) 0%, var(--bg-surface) 100%);
      border: 1px solid var(--border-subtle);
      border-radius: var(--radius-md);
      padding: 34px 30px;
      display: flex;
      flex-direction: column;
      gap: 20px;
      position: relative;
      transition: transform var(--transition), border-color var(--transition);
    }

    .feature-card:hover {
      transform: translateY(-4px);
      border-color: var(--border-bright);
    }

    .feature-top {
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .feature-icon {
      width: 46px;
      height: 46px;
      border-radius: var(--radius-sm);
      background: var(--gold-soft);
      border: 1px solid rgba(228, 182, 115, 0.25);
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--gold);
    }

    .feature-num {
      font-family: var(--font-mono);
      font-size: 0.78rem;
      color: var(--text-muted);
      letter-spacing: 0.14em;
    }

    .feature-title {
      font-family: var(--font-serif);
      font-size: 1.4rem;
      font-weight: 400;
      color: var(--text-primary);
    }

    .feature-text {
      color: var(--text-secondary);
      font-size: 0.94rem;
      line-height: 1.65;
    }

    .feature-meta {
      margin-top: auto;
      padding-top: 18px;
      border-top: 1px solid rgba(255, 255, 255, 0.05);
      font-family: var(--font-mono);
      font-size: 0.74rem;
      color: var(--neon-cyan);
      letter-spacing: 0.08em;
    }

    /* Timetable Section */
    .timetable-section {
      background: linear-gradient(180deg, rgba(17, 14, 26, 0.5) 0%, rgba(7, 6, 11, 0) 100%);
      border-top: 1px solid var(--border-subtle);
      border-bottom: 1px solid var(--border-subtle);
    }

    .route-schematic {
      background: var(--bg-surface);
      border: 1px solid var(--border-subtle);
      border-radius: var(--radius-md);
      padding: 22px 28px;
      margin-bottom: 24px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 24px;
    }

    .route-stops {
      display: flex;
      align-items: center;
      flex: 1;
      justify-content: space-between;
      position: relative;
    }

    .route-stops::before {
      content: "";
      position: absolute;
      left: 24px;
      right: 24px;
      top: 9px;
      height: 1px;
      background: linear-gradient(90deg, var(--terracotta), var(--gold), var(--neon-cyan));
      opacity: 0.55;
      z-index: 0;
    }

    .stop-node {
      position: relative;
      z-index: 1;
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 8px;
      text-align: center;
    }

    .stop-dot {
      width: 18px;
      height: 18px;
      border-radius: 50%;
      background: var(--bg-surface);
      border: 2px solid var(--gold);
      box-shadow: 0 0 0 4px var(--bg-surface);
    }

    .stop-node.origin .stop-dot {
      border-color: var(--terracotta);
    }

    .stop-node.terminus .stop-dot {
      border-color: var(--neon-cyan);
      box-shadow: 0 0 12px rgba(42, 245, 228, 0.5), 0 0 0 4px var(--bg-surface);
    }

    .stop-name {
      font-size: 0.84rem;
      font-weight: 500;
      color: var(--text-primary);
    }

    .stop-km {
      font-family: var(--font-mono);
      font-size: 0.68rem;
      color: var(--text-muted);
    }

    .timetable-board {
      background: var(--bg-surface);
      border: 1px solid var(--border-subtle);
      border-radius: var(--radius-md);
      overflow: hidden;
    }

    .board-head {
      display: grid;
      grid-template-columns: 1.1fr 1.6fr 1fr 1fr 0.8fr 1.1fr 0.9fr;
      gap: 16px;
      padding: 16px 28px;
      background: rgba(255, 255, 255, 0.025);
      border-bottom: 1px solid var(--border-subtle);
      font-family: var(--font-mono);
      font-size: 0.7rem;
      letter-spacing: 0.14em;
      text-transform: uppercase;
      color: var(--text-muted);
    }

    .board-row {
      display: grid;
      grid-template-columns: 1.1fr 1.6fr 1fr 1fr 0.8fr 1.1fr 0.9fr;
      gap: 16px;
      padding: 22px 28px;
      align-items: center;
      border-bottom: 1px solid rgba(255, 255, 255, 0.045);
      transition: background var(--transition);
      cursor: pointer;
    }

    .board-row:last-child {
      border-bottom: none;
    }

    .board-row:hover,
    .board-row.active {
      background: rgba(228, 182, 115, 0.06);
    }

    .train-code {
      font-family: var(--font-mono);
      font-size: 0.9rem;
      color: var(--gold);
      font-weight: 600;
    }

    .train-name {
      font-family: var(--font-serif);
      font-size: 1.12rem;
      color: var(--text-primary);
    }

    .train-route-sub {
      font-size: 0.78rem;
      color: var(--text-muted);
      margin-top: 2px;
    }

    .time-cell {
      font-family: var(--font-mono);
      font-size: 0.98rem;
      color: var(--text-primary);
    }

    .time-sub {
      display: block;
      font-size: 0.72rem;
      color: var(--text-muted);
      margin-top: 2px;
    }

    .platform-badge {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      width: 34px;
      height: 28px;
      border-radius: 4px;
      background: rgba(255, 255, 255, 0.04);
      border: 1px solid var(--border-subtle);
      font-family: var(--font-mono);
      font-size: 0.82rem;
      color: var(--text-primary);
    }

    .status-pill {
      display: inline-flex;
      align-items: center;
      gap: 7px;
      font-family: var(--font-mono);
      font-size: 0.72rem;
      padding: 5px 10px;
      border-radius: 999px;
      width: fit-content;
    }

    .status-boarding {
      color: var(--neon-cyan);
      background: rgba(42, 245, 228, 0.08);
      border: 1px solid rgba(42, 245, 228, 0.26);
    }

    .status-schedule {
      color: var(--gold);
      background: rgba(228, 182, 115, 0.08);
      border: 1px solid rgba(228, 182, 115, 0.26);
    }

    .status-limited {
      color: var(--neon-magenta);
      background: rgba(255, 59, 141, 0.08);
      border: 1px solid rgba(255, 59, 141, 0.28);
    }

    .row-action {
      text-align: right;
    }

    .row-btn {
      font-family: var(--font-mono);
      font-size: 0.74rem;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      padding: 8px 14px;
      border-radius: var(--radius-sm);
      border: 1px solid var(--border-bright);
      color: var(--gold);
      transition: all var(--transition);
    }

    .row-btn:hover {
      background: var(--gold);
      color: var(--bg-void);
    }

    /* Pricing Section */
    .billing-toggle {
      display: inline-flex;
      padding: 4px;
      border-radius: 999px;
      background: var(--bg-elevated);
      border: 1px solid var(--border-subtle);
    }

    .toggle-btn {
      font-family: var(--font-mono);
      font-size: 0.74rem;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      padding: 9px 18px;
      border-radius: 999px;
      color: var(--text-secondary);
      transition: all var(--transition);
    }

    .toggle-btn.active {
      background: var(--gold);
      color: var(--bg-void);
      font-weight: 600;
    }

    .pricing-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 24px;
      align-items: stretch;
    }

    .tier-card {
      background: var(--bg-surface);
      border: 1px solid var(--border-subtle);
      border-radius: var(--radius-md);
      padding: 36px 32px;
      display: flex;
      flex-direction: column;
      position: relative;
      transition: transform var(--transition), border-color var(--transition);
    }

    .tier-card:hover {
      transform: translateY(-4px);
      border-color: var(--border-bright);
    }

    .tier-card.featured {
      background: linear-gradient(180deg, #1b1728 0%, #100e18 100%);
      border-color: var(--gold);
      box-shadow: 0 24px 60px rgba(228, 182, 115, 0.1);
    }

    .tier-badge {
      position: absolute;
      top: -12px;
      right: 28px;
      background: linear-gradient(90deg, var(--gold), #f0cf99);
      color: var(--bg-void);
      font-family: var(--font-mono);
      font-size: 0.68rem;
      font-weight: 700;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      padding: 5px 12px;
      border-radius: 999px;
    }

    .tier-class {
      font-family: var(--font-mono);
      font-size: 0.74rem;
      letter-spacing: 0.15em;
      text-transform: uppercase;
      color: var(--gold);
    }

    .tier-name {
      font-family: var(--font-serif);
      font-size: 1.65rem;
      font-weight: 400;
      margin-top: 8px;
    }

    .tier-price-wrap {
      margin: 24px 0;
      padding-bottom: 24px;
      border-bottom: 1px solid var(--border-subtle);
      display: flex;
      align-items: baseline;
      gap: 10px;
    }

    .tier-price {
      font-family: var(--font-serif);
      font-size: 2.85rem;
      line-height: 1;
      color: var(--text-primary);
    }

    .tier-unit {
      font-family: var(--font-mono);
      font-size: 0.78rem;
      color: var(--text-muted);
    }

    .tier-desc {
      font-size: 0.92rem;
      color: var(--text-secondary);
      margin-bottom: 24px;
    }

    .tier-list {
      list-style: none;
      display: flex;
      flex-direction: column;
      gap: 13px;
      margin-bottom: 32px;
    }

    .tier-list li {
      display: flex;
      align-items: flex-start;
      gap: 12px;
      font-size: 0.9rem;
      color: var(--text-primary);
    }

    .tier-list li::before {
      content: "✦";
      color: var(--gold);
      font-size: 0.75rem;
      margin-top: 3px;
      flex-shrink: 0;
    }

    .tier-cta {
      margin-top: auto;
      width: 100%;
    }

    /* Testimonial Section */
    .testimonial-section {
      padding: 88px 0;
    }

    .testimonial-box {
      position: relative;
      background: linear-gradient(135deg, rgba(23, 20, 34, 0.92) 0%, rgba(12, 11, 18, 0.95) 100%);
      border: 1px solid var(--border-subtle);
      border-radius: var(--radius-lg);
      padding: 60px 72px;
      overflow: hidden;
    }

    .testimonial-box::before {
      content: "";
      position: absolute;
      top: 0;
      left: 0;
      right: 0;
      height: 2px;
      background: linear-gradient(90deg, var(--terracotta), var(--gold), var(--neon-cyan));
      opacity: 0.7;
    }

    .testimonial-grid {
      display: grid;
      grid-template-columns: 1fr auto;
      gap: 48px;
      align-items: center;
    }

    .quote-mark {
      font-family: var(--font-serif);
      font-size: 4rem;
      line-height: 0.6;
      color: var(--gold);
      opacity: 0.5;
      margin-bottom: 18px;
      display: block;
    }

    .quote-text {
      font-family: var(--font-serif);
      font-size: clamp(1.35rem, 2.2vw, 1.85rem);
      line-height: 1.45;
      color: var(--text-primary);
      font-weight: 400;
      max-width: 760px;
    }

    .quote-author {
      margin-top: 28px;
      display: flex;
      align-items: center;
      gap: 16px;
    }

    .author-avatar {
      width: 48px;
      height: 48px;
      border-radius: 50%;
      border: 1px solid var(--border-bright);
      background: radial-gradient(circle at 30% 30%, rgba(228, 182, 115, 0.35), rgba(42, 245, 228, 0.12));
      display: flex;
      align-items: center;
      justify-content: center;
      font-family: var(--font-serif);
      font-size: 1.1rem;
      color: var(--gold);
    }

    .author-name {
      font-weight: 600;
      font-size: 0.98rem;
      color: var(--text-primary);
    }

    .author-meta {
      font-family: var(--font-mono);
      font-size: 0.74rem;
      color: var(--text-secondary);
      margin-top: 2px;
    }

    .testimonial-stamp {
      text-align: right;
      padding: 22px 26px;
      border: 1px dashed var(--border-bright);
      border-radius: var(--radius-md);
      background: rgba(7, 6, 11, 0.45);
    }

    .stamp-code {
      font-family: var(--font-mono);
      font-size: 0.72rem;
      letter-spacing: 0.16em;
      color: var(--neon-cyan);
    }

    .stamp-route {
      font-family: var(--font-serif);
      font-size: 1.2rem;
      margin: 6px 0;
    }

    .stamp-stars {
      color: var(--gold);
      letter-spacing: 0.2em;
      font-size: 0.85rem;
    }

    /* Footer */
    .footer {
      border-top: 1px solid var(--border-subtle);
      background: #050408;
      padding: 72px 0 36px;
    }

    .footer-grid {
      display: grid;
      grid-template-columns: 1.4fr 0.8fr 0.8fr 1.2fr;
      gap: 48px;
      padding-bottom: 52px;
      border-bottom: 1px solid rgba(255, 255, 255, 0.06);
    }

    .footer-desc {
      margin-top: 16px;
      font-size: 0.9rem;
      color: var(--text-secondary);
      max-width: 310px;
      line-height: 1.65;
    }

    .footer-coords {
      margin-top: 20px;
      font-family: var(--font-mono);
      font-size: 0.72rem;
      color: var(--text-muted);
      letter-spacing: 0.1em;
    }

    .footer-heading {
      font-family: var(--font-mono);
      font-size: 0.74rem;
      letter-spacing: 0.16em;
      text-transform: uppercase;
      color: var(--gold);
      margin-bottom: 18px;
    }

    .footer-links {
      list-style: none;
      display: flex;
      flex-direction: column;
      gap: 11px;
    }

    .footer-links a {
      font-size: 0.9rem;
      color: var(--text-secondary);
      transition: color var(--transition);
    }

    .footer-links a:hover {
      color: var(--text-primary);
    }

    .dispatch-form {
      display: flex;
      gap: 8px;
      margin-top: 14px;
    }

    .dispatch-input {
      flex: 1;
      min-width: 0;
      padding: 11px 14px;
      border-radius: var(--radius-sm);
      border: 1px solid var(--border-subtle);
      background: var(--bg-surface);
      color: var(--text-primary);
      font-size: 0.88rem;
      outline: none;
      transition: border-color var(--transition);
    }

    .dispatch-input:focus {
      border-color: var(--gold);
    }

    .dispatch-msg {
      margin-top: 10px;
      font-family: var(--font-mono);
      font-size: 0.74rem;
      color: var(--neon-cyan);
      min-height: 1.2em;
    }

    .footer-bottom {
      padding-top: 28px;
      display: flex;
      justify-content: space-between;
      align-items: center;
      font-size: 0.82rem;
      color: var(--text-muted);
    }

    /* Reservation Modal */
    .modal-backdrop {
      position: fixed;
      inset: 0;
      z-index: 100;
      background: rgba(5, 4, 9, 0.82);
      backdrop-filter: blur(8px);
      display: none;
      align-items: center;
      justify-content: center;
      padding: 24px;
    }

    .modal-backdrop.open {
      display: flex;
    }

    .modal-card {
      width: 100%;
      max-width: 520px;
      background: var(--bg-elevated);
      border: 1px solid var(--border-bright);
      border-radius: var(--radius-lg);
      padding: 34px;
      position: relative;
      box-shadow: 0 30px 90px rgba(0, 0, 0, 0.75);
    }

    .modal-close {
      position: absolute;
      top: 20px;
      right: 20px;
      width: 34px;
      height: 34px;
      border-radius: 50%;
      border: 1px solid var(--border-subtle);
      color: var(--text-secondary);
      font-size: 1.1rem;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .modal-close:hover {
      color: var(--text-primary);
      border-color: var(--gold);
    }

    .form-group {
      margin-top: 18px;
      display: flex;
      flex-direction: column;
      gap: 7px;
    }

    .form-label {
      font-family: var(--font-mono);
      font-size: 0.72rem;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      color: var(--text-secondary);
    }

    .form-select, .form-input {
      padding: 12px 14px;
      border-radius: var(--radius-sm);
      border: 1px solid var(--border-subtle);
      background: var(--bg-surface);
      color: var(--text-primary);
      font-size: 0.92rem;
      font-family: var(--font-sans);
      outline: none;
    }

    .form-select:focus, .form-input:focus {
      border-color: var(--gold);
    }

    .ticket-confirm {
      display: none;
      margin-top: 18px;
      padding: 22px;
      border-radius: var(--radius-md);
      background: rgba(42, 245, 228, 0.06);
      border: 1px solid rgba(42, 245, 228, 0.28);
    }

    .ticket-confirm.visible {
      display: block;
    }

    /* Responsive Breakpoints */
    @media (max-width: 1024px) {
      .hero-top {
        grid-template-columns: 1fr;
        gap: 24px;
      }
      .features-grid,
      .pricing-grid {
        grid-template-columns: 1fr;
      }
      .board-head {
        display: none;
      }
      .board-row {
        grid-template-columns: 1fr 1fr;
        gap: 12px;
      }
      .row-action {
        grid-column: span 2;
        text-align: left;
      }
      .testimonial-grid {
        grid-template-columns: 1fr;
      }
      .testimonial-stamp {
        text-align: left;
      }
      .footer-grid {
        grid-template-columns: 1fr 1fr;
      }
    }

    @media (max-width: 760px) {
      .container {
        padding: 0 20px;
      }
      .nav-links,
      .nav-status {
        display: none;
      }
      .nav-links.mobile-open {
        display: flex;
        flex-direction: column;
        position: absolute;
        top: 76px;
        left: 0;
        right: 0;
        background: var(--bg-surface);
        border-bottom: 1px solid var(--border-subtle);
        padding: 24px;
        gap: 20px;
      }
      .menu-toggle {
        display: inline-flex;
      }
      .section {
        padding: 68px 0;
      }
      .section-header {
        flex-direction: column;
        align-items: flex-start;
      }
      .hero-telemetry {
        grid-template-columns: repeat(2, 1fr);
      }
      .telemetry-cell:nth-child(2) {
        border-right: none;
      }
      .telemetry-cell:nth-child(1),
      .telemetry-cell:nth-child(2) {
        border-bottom: 1px solid var(--border-subtle);
      }
      .route-schematic {
        overflow-x: auto;
      }
      .route-stops {
        min-width: 500px;
      }
      .testimonial-box {
        padding: 36px 26px;
      }
      .footer-grid {
        grid-template-columns: 1fr;
        gap: 32px;
      }
      .footer-bottom {
        flex-direction: column;
        gap: 12px;
        text-align: center;
      }
    }
  </style>
</head>
<body>

