  <script>
    // Mobile Navigation Toggle
    const menuToggle = document.getElementById('menuToggle');
    const navLinks = document.getElementById('navLinks');

    menuToggle.addEventListener('click', () => {
      navLinks.classList.toggle('mobile-open');
    });

    navLinks.querySelectorAll('a').forEach(link => {
      link.addEventListener('click', () => {
        navLinks.classList.remove('mobile-open');
      });
    });

    // Interactive Timetable Row Highlight
    const boardRows = document.querySelectorAll('.board-row');
    boardRows.forEach(row => {
      row.addEventListener('click', (e) => {
        if (e.target.closest('button')) return;
        boardRows.forEach(r => r.classList.remove('active'));
        row.classList.add('active');
      });
    });

    // Pricing One-Way / Round-Trip Toggle
    function setTripType(type) {
      const oneWayBtn = document.getElementById('oneWayBtn');
      const roundTripBtn = document.getElementById('roundTripBtn');
      const prices = document.querySelectorAll('.tier-price');
      const units = document.querySelectorAll('.tier-unit');

      if (type === 'round') {
        oneWayBtn.classList.remove('active');
        roundTripBtn.classList.add('active');
        prices.forEach(el => el.textContent = el.dataset.round);
        units.forEach(el => el.textContent = el.dataset.unitRound);
      } else {
        roundTripBtn.classList.remove('active');
        oneWayBtn.classList.add('active');
        prices.forEach(el => el.textContent = el.dataset.oneway);
        units.forEach(el => el.textContent = el.dataset.unitOneway);
      }
    }

    // Reservation Modal Logic
    const modal = document.getElementById('bookingModal');
    const modalTrain = document.getElementById('modalTrain');
    const modalTier = document.getElementById('modalTier');
    const modalGuest = document.getElementById('modalGuest');
    const bookingForm = document.getElementById('bookingForm');
    const ticketConfirm = document.getElementById('ticketConfirm');
    const ticketSummary = document.getElementById('ticketSummary');

    function openModal(tier, train) {
      ticketConfirm.classList.remove('visible');
      if (tier) {
        for (const opt of modalTier.options) {
          if (opt.value.toLowerCase().includes(tier.toLowerCase().split(' ')[0])) {
            modalTier.value = opt.value;
            break;
          }
        }
      }
      if (train) {
        modalTrain.value = train;
      }
      modal.classList.add('open');
      setTimeout(() => modalGuest.focus(), 60);
    }

    function closeModal() {
      modal.classList.remove('open');
    }

    modal.addEventListener('click', (e) => {
      if (e.target === modal) closeModal();
    });

    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && modal.classList.contains('open')) closeModal();
    });

    bookingForm.addEventListener('submit', (e) => {
      e.preventDefault();
      const guest = modalGuest.value.trim() || 'Traveler';
      const train = modalTrain.value;
      const tier = modalTier.value;
      const code = 'DL-' + Math.floor(1000 + Math.random() * 9000);
      ticketSummary.innerHTML =
        `<strong>${guest}</strong> &bull; Ref <strong>${code}</strong><br>` +
        `Service: ${train}<br>` +
        `Accommodation: ${tier}`;
      ticketConfirm.classList.add('visible');
    });

    // Footer Dispatch Form
    const dispatchForm = document.getElementById('dispatchForm');
    const dispatchEmail = document.getElementById('dispatchEmail');
    const dispatchMsg = document.getElementById('dispatchMsg');

    dispatchForm.addEventListener('submit', (e) => {
      e.preventDefault();
      const email = dispatchEmail.value.trim();
      if (!email) return;
      dispatchMsg.textContent = `Confirmed: Nightly dispatches queued for ${email}.`;
      dispatchEmail.value = '';
    });
  </script>
</body>
